import itertools, json
Aopts=['MQR','PQR','KNR','LNP','NPR']
Bopts=['KMQ','KPR','LPR','KNQ','KPQ']
Adays=[{1},{1,7},{3,6},{3},{1,5,7}]
Bdays=[{6,8},{2,7},{3,7,8},{1,2,4},{4}]
A=[x for x in itertools.product(*Aopts) if len(set(x))==5]
B=[x for x in itertools.product(*Bopts) if len(set(x))==5]
n=0; low=8; high=-1; lw=None; hw=None; hist={}
for a in A:
 for b in B:
  common=set(a)&set(b)
  if len(common)!=3 or len(common & set('KLQ'))!=1: continue
  n+=1
  days={p:set() for p in 'KLMNPQR'}
  for p,d in zip(a,Adays): days[p].update(d)
  for p,d in zip(b,Bdays): days[p].update(d)
  score=sum(len(d)>=3 for d in days.values())
  hist[score]=hist.get(score,0)+1
  if score<low: low=score; lw={'A':''.join(a),'B':''.join(b)}
  if score>high: high=score; hw={'A':''.join(a),'B':''.join(b)}
print(json.dumps({'feasible_linkages':n,'bounds':[low,high],'low_witness':lw,'high_witness':hw,'decision':'confirmed' if low>=5 else 'excluded' if high<5 else 'undetermined'}))
print('histogram',hist)
print('injective candidates',len(A),len(B))

